// Selected original achievement methods; generated by prepare_partner_achievements.py.
using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;

namespace Zjcs.Official.Partners
{
    public sealed class PartnerFriendshipAchievementRules
    {
        /*ENUMS*/
        public abstract class AchievementDataKey
        {
            public abstract AchievementType AchievementType { get; }
            public abstract ushort GetOpCode();
            /*BASE_KEY_METHODS*/
        }
        /*KEYS*/
        public sealed class AchievementData
        {
            public int Level;
            public AchievementDataKey AchievementDataKey;
            public int NpcClassId => AchievementDataKey is AchievementDataKeyNpcFriendshipLevel normal
                ? normal.NpcClassId : ((AchievementDataKeyStarGodNpcFriendshipLevel)AchievementDataKey).NpcClassId;
        }
        public sealed class RawInfo
        {
            public int Id, Group;
            public AchievementType AchievementType;
            public AchievementData AchievementData;
            public Dictionary<int, long> Reward;
        }
        public readonly struct AchievementInfo
        {
            public static readonly AchievementInfo sEmpty = new AchievementInfo(0, 0, null);
            private readonly RawInfo raw;
            public readonly int StartRawId, Index;
            public AchievementInfo(RawInfo raw, int index) { this.raw = raw; StartRawId = raw.Id; Index = index; }
            private AchievementInfo(int rawId, int index, RawInfo raw) { StartRawId = rawId; Index = index; this.raw = raw; }
            public int Group => raw.Group;
            public AchievementType AchievementType => raw.AchievementType;
            public AchievementData AchievementData => raw.AchievementData;
            public Dictionary<int, long> Reward => raw.Reward;
            public int Id => GroupAndIndexToId(Group, Index);
            public bool IsValid => StartRawId >= 0;
            public bool IsInvalid => !IsValid;
            /*INFO_METHODS*/
        }
        public sealed class PlayerAchievementRecordDataWrap
        {
            public int CanRewardsMaxIndex = -1, GotRewardMaxIndex = -1;
            public Action<long, int> NonSequentialClaim;
            /*RECORD_METHODS*/
        }
        public sealed class PlayerAchievement
        {
            public long PlayerId;
            public AchievementType AchievementType;
            public readonly Dictionary<int, PlayerAchievementRecordDataWrap> GroupRecords = new Dictionary<int, PlayerAchievementRecordDataWrap>();
            /*GROUP_RECORD*/
        }
        public sealed class Player
        {
            private readonly PartnerFriendshipAchievementRules Parser;
            private readonly Func<int, (bool found, int level)> friendship;
            public readonly Dictionary<AchievementType, PlayerAchievement> AchievementManager = new Dictionary<AchievementType, PlayerAchievement>();
            public long Id { get; }
            public Player(PartnerFriendshipAchievementRules parser, long id, Func<int, (bool found, int level)> friendship)
            { Parser = parser ?? throw new ArgumentNullException(nameof(parser)); Id = id; this.friendship = friendship ?? throw new ArgumentNullException(nameof(friendship)); }
            public bool TryGetNpcFriendshipLevel(int id, out int level) { var value = friendship(id); level = value.level; return value.found; }
            public event Action<int> OnRecordAlreadyGotAchievementReward, OnRecordAlreadyGotAchievementRewardByGroupId;
            public event Action OnRecordAlreadyGotAchievementRewardBatch;
            public event Action<AchievementDataKey> OnUpdateAchievementData;
            /*PLAYER_METHODS*/
        }
        public sealed class AchievementTaskNpcFriendshipLevel
        {
            private readonly PartnerFriendshipAchievementRules Parser;
            public AchievementTaskNpcFriendshipLevel(PartnerFriendshipAchievementRules parser) { Parser = parser; }
            /*NORMAL_TASK*/
        }
        public sealed class AchievementTaskStarGodNpcFriendshipLevel
        {
            private readonly PartnerFriendshipAchievementRules Parser;
            public AchievementTaskStarGodNpcFriendshipLevel(PartnerFriendshipAchievementRules parser) { Parser = parser; }
            /*STAR_TASK*/
        }
        private readonly Dictionary<int, List<AchievementInfo>> groups = new Dictionary<int, List<AchievementInfo>>();
        private readonly Dictionary<int, AchievementInfo> infos = new Dictionary<int, AchievementInfo>();
        private readonly Dictionary<AchievementDataKey, int> keyToGroup = new Dictionary<AchievementDataKey, int>();
        private readonly Dictionary<int, AchievementDataKey> groupToKey = new Dictionary<int, AchievementDataKey>();
        public IEnumerable<int> GroupIds => groups.Keys;
        public int Count => infos.Count;
        public PartnerFriendshipAchievementRules(Func<string, IEnumerable<Dictionary<string, object>>> rows)
        {
            if (rows == null) throw new ArgumentNullException(nameof(rows));
            var rawGroups = new Dictionary<int, List<RawInfo>>();
            var keyCache = new Dictionary<(AchievementType, string), AchievementDataKey>();
            foreach (var row in rows("achievement"))
            {
                var type = (AchievementType)Convert.ToInt32(row["AchievementType"]);
                if (type != AchievementType.NpcFriendshipLevel && type != AchievementType.StarGodNpcFriendshipLevel) continue;
                // Both selected types have only independent templates. A new
                // source version must restore its cycle path before use.
                if (Convert.ToInt32(row["CycleCount"]) != 0 || !string.IsNullOrEmpty((string)row["CycleIncrementParams"]))
                    throw new NotSupportedException("Review original friendship achievement cycle templates.");
                string parameters = (string)row["GroupParams"];
                if (!keyCache.TryGetValue((type, parameters), out var key))
                    keyCache.Add((type, parameters), key = CreateKey(type, parameters));
                var data = JsonConvert.DeserializeObject<AchievementData>((string)row["CompleteParams"]);
                data.AchievementDataKey = key;
                var value = new RawInfo { Id = Convert.ToInt32(row["Id"]), Group = Convert.ToInt32(row["Group"]),
                    AchievementType = type, AchievementData = data,
                    Reward = ((Dictionary<string, object>)row["Reward"]).ToDictionary(p => int.Parse(p.Key, System.Globalization.CultureInfo.InvariantCulture), p => Convert.ToInt64(p.Value)) };
                if (!rawGroups.TryGetValue(value.Group, out var list)) rawGroups.Add(value.Group, list = new List<RawInfo>());
                list.Add(value);
                keyToGroup[key] = value.Group; groupToKey[value.Group] = key;
            }
            foreach (var pair in rawGroups)
            {
                pair.Value.Sort((a, b) => a.Id - b.Id);
                var list = new List<AchievementInfo>();
                for (int index = 0; index < pair.Value.Count; index++)
                {
                    var info = new AchievementInfo(pair.Value[index], index);
                    list.Add(info); infos.Add(info.Id, info);
                }
                groups.Add(pair.Key, list);
            }
        }
        public AchievementDataKey CreateKey(AchievementType type, string json)
        {
            if (string.IsNullOrEmpty(json)) return new AchievementDataKeyNormal(type);
            if (type == AchievementType.NpcFriendshipLevel) return (AchievementDataKey)JsonConvert.DeserializeObject<AchievementDataKeyNpcFriendshipLevel>(json) ?? new AchievementDataKeyNormal(type);
            if (type == AchievementType.StarGodNpcFriendshipLevel) return (AchievementDataKey)JsonConvert.DeserializeObject<AchievementDataKeyStarGodNpcFriendshipLevel>(json) ?? new AchievementDataKeyNormal(type);
            throw new ArgumentOutOfRangeException(nameof(type));
        }
        public int GetAchievementKeyToGroup(AchievementDataKey key) => key.Equals(AchievementDataKeyNormal.None) ? 0 : keyToGroup.TryGetValue(key, out int group) ? group : -1;
        public bool TryGetAchievementGroupToKey(int group, out AchievementDataKey key) => groupToKey.TryGetValue(group, out key);
        public AchievementDataKey GetAchievementGroupToKey(int group) => groupToKey.TryGetValue(group, out var key) ? key : AchievementDataKeyNormal.None;
        public AchievementInfo GetAchievementInfoById(int id) => GetAchievementInfoByGroupAndIndex(AchievementInfo.GetGroupAndIndex(id).groupId, AchievementInfo.GetGroupAndIndex(id).index);
        public AchievementInfo GetAchievementInfoByGroupAndIndex(int group, int index) => groups.TryGetValue(group, out var list) && index >= 0 && index < list.Count ? list[index] : AchievementInfo.sEmpty;
        public IReadOnlyList<AchievementInfo> GetAchievementInfoListByGroupId(int group) => groups.TryGetValue(group, out var list) ? list : Array.Empty<AchievementInfo>();
    }
}
